'use strict';
const chapters=['智能起源与发展','知识表示与推理','机器学习方法','神经网络与深度学习','大模型与生成技术','应用、前沿与风险'];
let cards=[];
const getCard=id=>cards.find(c=>c.id===id);
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let saved=[],learned=[],docs=[],tab='home',chapterFilter=-1,query='',messages=[];
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const navs=[['home','⌂','学习'],['library','▤','知识库'],['map','⌘','关系图'],['ask','✧','答疑'],['review','◷','复习']];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function pageHead(title,sub,en){return `<div class="page-top"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p class="muted" style="margin-bottom:0">${sub}</p></div><a href="#materials" class="btn ghost">${isAdmin()?'＋ 导入资料':'课程资料'}</a></div>`}
function cardHTML(c){if(!c)return "";return `<button class="knowledge" onclick="openCard(${c.id})"><div class="card-top"><span class="category">${chapters[c.chapter]}</span><span>${saved.includes(c.id)?'★':'↗'}</span></div><h3>${c.title}</h3><p>${c.definition}</p><div class="card-footer"><span>教材与课件知识卡片</span><span>${learned.includes(c.id)?'✓ 已掌握':'查看知识点 →'}</span></div></button>`}
function searchHTML(){return `<form class="searchbar" onsubmit="searchSubmit(event)"><span class="search-icon">⌕</span><input aria-label="检索课程知识" name="q" value="${esc(query)}" placeholder="搜索概念、问题或资料中的内容…" autocomplete="off"><button class="btn" type="submit">检索</button></form>`}
function searchSubmit(e){showFavorites=false;showAnnotations=false;e.preventDefault();query=e.target.elements.q.value.trim();chapterFilter=-1;if(tab!=='library')location.hash='library';else render()}
function exampleHome(){return pageHead('今天，探索一点新知。','把零散的知识，连接成自己的理解。','YOUR LEARNING SPACE')+`<section class="hero"><div><div class="eyebrow">COURSE 01 / 人工智能</div><h2>人工智能概论</h2><p>从基本概念到学习算法，循着知识的脉络，<br>一步一步理解人工智能。</p><button class="btn light" onclick="openChapter(0)">开始学习 <span>↗</span></button></div><div class="hero-graphic" aria-hidden="true"><i class="orbit"></i><i class="orbit"></i><i class="orbit"></i><span class="core">AI</span><i class="planet"></i><i class="planet"></i></div></section><div class="stats"><div class="stat"><div><div class="stat-label">课程章节</div><strong>06</strong> <small>章</small></div><span class="stat-icon">▤</span></div><div class="stat"><div><div class="stat-label">已掌握知识</div><strong>${String(learned.length).padStart(2,'0')}</strong> <small>/ ${cards.length}</small></div><span class="stat-icon">◎</span></div><div class="stat"><div><div class="stat-label">我的收藏</div><strong>${String(saved.length).padStart(2,'0')}</strong> <small>张卡片</small></div><span class="stat-icon">☆</span></div></div><div class="section-head"><h2>想了解什么？</h2><span class="muted">从一个问题开始</span></div>${searchHTML()}<div class="tags"><span class="muted">试着搜</span>${['监督学习','神经网络','过拟合'].map(t=>`<button class="chip" onclick="quickSearch('${t}')">${t}</button>`).join('')}</div><div class="two-col"><section><div class="section-head"><h2>沿着章节，系统学习</h2><a class="text-link" href="#library">全部知识 ↗</a></div><div class="chapter-list">${chapters.slice(0,4).map((c,i)=>`<button class="chapter" onclick="openChapter(${i})"><span class="chapter-num">0${i+1}</span><span class="chapter-info"><strong>${c}</strong><small>${cards.filter(x=>x.chapter===i).length} 个知识点 · ${cards.filter(x=>x.chapter===i&&learned.includes(x.id)).length} 个已掌握</small></span><span class="arrow">↗</span></button>`).join('')}</div></section><section class="map-preview"><div class="section-head"><h2>让知识连接起来</h2><a class="text-link" href="#map">探索 ↗</a></div><div class="panel">${miniMap()}<p class="map-note">概念有联系，学习有路径。</p></div></section></div><div class="section-head"><h2>值得理解的知识点</h2><span class="muted">先理解，再记忆</span></div><div class="knowledge-grid">${[6,8,10].map(i=>cardHTML(getCard(i))).join('')}</div><div class="note">知识卡片依据现有教材与课件整理，可在卡片中回到对应原页。</div>`}
function miniMap(){return `<svg class="mini-map" viewBox="0 0 320 235" role="img" aria-label="人工智能包含机器学习，机器学习包含深度学习"><g fill="none" stroke="#c4d2b7"><path d="M160 52V94M160 125L76 168M160 125L242 168"/><circle cx="160" cy="118" r="76" stroke-dasharray="3 5" opacity=".4"/></g><g font-size="11" text-anchor="middle" font-family="sans-serif"><rect x="103" y="20" width="114" height="38" rx="19" fill="#244d39"/><text x="160" y="44" fill="#fff">人工智能</text><rect x="107" y="96" width="106" height="36" rx="18" fill="#e4edcf"/><text x="160" y="119" fill="#536e42">机器学习</text><rect x="21" y="169" width="112" height="36" rx="18" fill="#f2f4e9"/><text x="77" y="192" fill="#75836b">深度学习</text><rect x="190" y="169" width="106" height="36" rx="18" fill="#f2f4e9"/><text x="243" y="192" fill="#75836b">传统学习方法</text></g></svg>`}
function quickSearch(q){showFavorites=false;showAnnotations=false;query=q;chapterFilter=-1;if(tab==='library')render();else location.hash='library'}
function openChapter(i){showFavorites=false;showAnnotations=false;chapterFilter=i;query='';if(tab==='library')render();else location.hash='library'}
function setFilter(i){chapterFilter=i;render()}
function legacyFileSearchDocs(q){if(!q)return [];const tokens=q.toLowerCase().split(/\s+/).filter(Boolean);return docs.flatMap(d=>{const lower=d.text.toLowerCase();const token=tokens.find(t=>lower.includes(t)||d.name.toLowerCase().includes(t));if(!token)return [];const pos=Math.max(0,lower.indexOf(token));return [{...d,snippet:d.text.slice(Math.max(0,pos-70),pos+200)}]})}
function libraryBase(){const found=cards.filter(c=>(chapterFilter<0||c.chapter===chapterFilter)&&(!query||[c.title,c.definition,c.tip,c.example,chapters[c.chapter]].join(' ').toLowerCase().includes(query.toLowerCase())));const matches=searchDocs(query);return pageHead('知识，有迹可循。','按章节梳理概念，也可以直接搜索你想知道的。','KNOWLEDGE LIBRARY')+searchHTML()+`<div class="tags"><button class="chip ${chapterFilter<0?'active':''}" onclick="setFilter(-1)">全部章节</button>${chapters.map((c,i)=>`<button class="chip ${chapterFilter===i?'active':''}" onclick="setFilter(${i})">${i+1}. ${c}</button>`).join('')}</div><div class="section-head"><h2>${query?'“'+esc(query)+'” 的检索结果':chapterFilter<0?'课程知识卡片':chapters[chapterFilter]}</h2><span class="muted">${found.length} 个知识点</span></div><div class="knowledge-grid">${found.map(cardHTML).join('')}</div>${!found.length?'<div class="empty">没有匹配的知识点。试试更短的关键词，例如“学习”或“搜索”。</div>':''}${matches.length?`<div class="section-head"><h2>教材与课件中的相关内容</h2></div>${matches.map(d=>`<div class="panel" style="margin-bottom:12px"><h3>${highlightText(d.name)}</h3><p class="muted">${highlightText(d.snippet)}</p><small class="muted">${d.bookPage?'来源：教材 · '+d.printLabel:d.coursePage?'来源：导入课件 · 第 '+d.pageNumber+' 页':d.documentId?'来源：管理员上传 · 第 '+d.pageNumber+' 页':'来源：管理员上传资料'}</small>${d.documentId?`<button class="text-link" onclick="openDocument('${d.documentId}',${d.pageNumber})">阅读本页 ↗</button>`:''}${d.bookPage?`<button class="text-link" onclick="openTextbook('${d.bookPage}')">查看教材本页 ↗</button>`:''}${d.coursePage?`<button class="text-link" onclick="openCourse('${d.coursePage}')">阅读本页 ↗</button>`:''}</div>`).join('')}`:''}`}
function openCard(id){if(!user||!getCard(id))return;const c=getCard(id);activeCard=id;rememberPage(true);$('#detail-content').innerHTML=`<div class="dialog-top"><span class="category">第 ${c.chapter+1} 章 · ${chapters[c.chapter]}</span><button class="close" aria-label="关闭卡片" onclick="document.querySelector('#detail').close()">×</button></div><h1>${c.title}</h1><p class="detail-definition">${c.definition}</p><div class="detail-label">用一个例子理解</div><p class="example">${c.example}</p><div class="detail-label">理解要点</div><p>${c.tip}</p><p class="muted">说明、例子与要点根据已导入资料整理，便于理解。</p><div class="card-details-note"><div class="detail-label">回到学习资料</div><div class="card-source-links">${c.sources.map(s=>`<button class="source-link" onclick="openCardSource(${id},'${s.kind}','${s.pageId}')">${esc(s.label)} ↗</button>`).join('')}</div></div><div class="detail-actions"><button class="btn" onclick="markLearned(${id})">${learned.includes(id)?'✓ 已掌握 · 点击撤销':'标记为已掌握'}</button><button class="btn ghost" onclick="saveCard(${id})">${saved.includes(id)?'★ 已收藏':'☆ 收藏卡片'}</button><button class="btn ghost" onclick="askCard(${id})">相关问题 ↗</button></div>`;if(!$('#detail').open)$('#detail').showModal()}
function markLearned(id){learned=learned.includes(id)?learned.filter(i=>i!==id):[...learned,id];persist();render();openCard(id)}
function saveCard(id){saved=saved.includes(id)?saved.filter(i=>i!==id):[...saved,id];persist();render();openCard(id)}
function askCard(id){$('#detail').close();const q=getCard(id).question;if(tab==='ask'){addQuestion(q)}else{location.hash='ask';setTimeout(()=>addQuestion(q),30)}}
function ask(){return aiAskPage()}
function submitQuestion(e){e.preventDefault();const q=e.target.elements.question.value.trim();if(q)addQuestion(q)}
function addQuestion(q){return aiAddQuestion(q)}
function answerQuiz(el,correct){el.classList.add(correct?'correct':'wrong');$('#quiz-feedback').textContent=correct?'回答正确。监督学习利用带标签的样本，学习输入与目标输出之间的映射。':'再想一想：关键在于训练数据是否提供目标标签。A、C 描述的是无监督学习的常见场景。';if(correct)document.querySelectorAll('#quiz button').forEach(b=>b.disabled=true)}
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}});
window.addEventListener('hashchange',route);

let activeDocument=null,documentPage=1;
let textbook=null,textbookEnabled=false,bookPage=null;
let course=null,courseEnabled=false,coursePage=null;
let user=null,ready=false,authMode='login',authBusy=false,activeCard=null,history=[],studentsList=[],syncStatus='',restoring=false;
let syncQueue=Promise.resolve(),syncFailed=false,scrollTimer,bootCount=0;
const isAdmin=()=>user?.role==='admin';
async function api(path,options={}){const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'X-Study-Request':'1',...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}});const data=await response.json();if(!response.ok){const error=new Error(data.error||'请求失败');error.status=response.status;throw error}return data}
function clearUser(){aiReset();showFavorites=false;cards=[];studied={textbook:[],course:[]};annotations=[];showAnnotations=false;annotationFilter="all";mapNode="book";mapRelation="all";mapSearch="";reviewFilter="all";pendingExcerpt="";resetReview();activeDocument=null;documentPage=1;resetTextbookImages();textbook=null;textbookEnabled=false;bookPage=null;user=null;course=null;courseEnabled=false;coursePage=null;saved=[];learned=[];docs=[];history=[];messages=[];studentsList=[];activeCard=null;query='';chapterFilter=-1;tab='home';if($('#detail').open)$('#detail').close()}
function authPage(){return `<section class="auth-card panel"><div class="eyebrow">WELCOME TO STUDY SPACE</div><h1>${authMode==='activate'?'第一次使用，设置密码。':'登录你的学习空间。'}</h1><p class="muted">学生使用名单中的学号，无需手机号。管理员使用管理员账号。</p><div class="tags auth-tabs"><button class="chip ${authMode==='login'?'active':''}" onclick="setAuthMode('login')">账号登录</button><button class="chip ${authMode==='activate'?'active':''}" onclick="setAuthMode('activate')">首次使用</button></div><form id="auth-form" class="auth-form" onsubmit="authenticate(event)"><label>${authMode==='activate'?'学号':'学号 / 管理员账号'}<input name="id" autocomplete="username" maxlength="40" required placeholder="${authMode==='activate'?'输入名单中的学号':'输入学号或管理员账号'}"></label>${authMode==='activate'?'<label>姓名<input name="name" autocomplete="name" maxlength="40" placeholder="与名单中的姓名一致" required></label>':''}<label>${authMode==='activate'?'设置密码':'密码'}<input name="password" type="password" autocomplete="${authMode==='activate'?'new-password':'current-password'}" minlength="${authMode==='activate'?8:1}" maxlength="128" required placeholder="${authMode==='activate'?'至少 8 位':'输入密码'}"></label>${authMode==='activate'?'<label>再次输入密码<input name="confirmPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="再次输入相同密码"></label>':''}<p id="auth-error" class="form-error" role="alert"></p><button class="btn" id="auth-submit" type="submit">${authMode==='activate'?'设置密码并登录':'登录'} <span>↗</span></button></form><p class="muted" style="margin:20px 0 0">${authMode==='activate'?'账号须已导入名单，密码只能在首次使用时设置。已激活账号请返回登录。':'第一次使用请先点击“首次使用”设置密码。忘记密码请联系课程管理员。'}</p></section>`}
function setAuthMode(mode){if(authBusy)return;const id=$('#auth-form')?.elements.id.value||'';authMode=mode;render();$('#auth-form').elements.id.value=id}
async function authenticate(e){e.preventDefault();if(authBusy)return;const form=e.target,b=Object.fromEntries(new FormData(form));if(authMode==='activate'&&b.password!==b.confirmPassword){$('#auth-error').textContent='两次密码不一致，请重新输入';return}authBusy=true;$('#auth-submit').disabled=true;$('#auth-error').textContent='';try{const result=await api('/auth/'+(authMode==='activate'?'activate':'login'),{method:'POST',body:JSON.stringify(b)});if(result.activationRequired){authBusy=false;authMode='activate';render();$('#auth-form').elements.id.value=b.id;$('#auth-error').textContent=result.message;return}await startSession(result.user);toast('登录成功，已载入该账号的学习记录')}catch(err){if(user){clearUser();ready=true;render()}$('#auth-error').textContent=err.message}finally{authBusy=false;if($('#auth-submit'))$('#auth-submit').disabled=false}}
async function startSession(account){resetTextbookImages();user=account;ready=false;render();const [stateResult,docResult,courseResult,bookResult,cardResult,aiResult]=await Promise.all([api('/state'),api('/documents'),api('/course'),api('/textbook'),api('/knowledge-cards'),api('/ai/status').catch(()=>({configured:false,model:'deepseek-flash'}))]);aiState=aiResult;cards=cardResult.cards;textbook=bookResult.textbook;textbookEnabled=bookResult.enabled;course=courseResult.course;courseEnabled=courseResult.enabled;const s=stateResult.state;studied=s.studied||{textbook:[],course:[]};annotations=s.annotations||[];resetReview();saved=s.saved;learned=s.learned;history=s.history;docs=docResult.documents;messages=[];studentsList=[];syncFailed=false;syncStatus='学习记录已同步';const p=s.lastPage;restoring=true;query=p.query||'';chapterFilter=p.chapterFilter??-1;tab=p.route||'home';coursePage=p.coursePage||null;bookPage=p.bookPage||null;activeDocument=p.documentId||null;documentPage=p.documentPage||1;if(tab==='students'&&!isAdmin())tab='home';activeCard=null;ready=true;window.history.replaceState(null,'','#'+tab);render();if(p.cardId!==null&&getCard(p.cardId))openCard(p.cardId);window.scrollTo(0,p.scroll||0);setTimeout(()=>{restoring=false},50)}
async function boot(){const serial=++bootCount;try{const result=await api('/auth/me');if(serial!==bootCount)return;await startSession(result.user)}catch(err){if(serial!==bootCount)return;clearUser();ready=true;render();if(err.status!==401)$('#auth-error').innerHTML=esc(err.message)+' <button type="button" class="text-link" onclick="boot()">重试连接</button>'}}
function snapshot(){return {route:tab,query:query.slice(0,200),chapterFilter,scroll:Math.min(100000,Math.max(0,Math.round(window.scrollY||0))),cardId:activeCard,coursePage:tab==='course'?coursePage:null,bookPage:tab==='textbook'?bookPage:null,documentId:tab==='document'?activeDocument:null,documentPage:tab==='document'?documentPage:null}}
function queueState(patch){if(!user||!ready||restoring)return;const id=user.id,body=JSON.stringify({userId:id,...patch});syncStatus='正在保存…';const task=async()=>{if(user?.id!==id)return;try{const r=await api('/state',{method:'PATCH',body});if(user?.id!==id)return;history=r.history;syncFailed=false;syncStatus='学习记录已同步';updateSyncLabel()}catch(err){if(user?.id!==id)return;syncFailed=true;syncStatus='保存失败，点击重试';updateSyncLabel();if(err.status===401){clearUser();ready=true;render();$('#auth-error').textContent='登录已过期，请重新登录'}else toast('学习记录未保存：'+err.message)}};syncQueue=syncQueue.then(task,task);updateSyncLabel()}
function persist(){queueState({saved:[...saved],learned:[...learned],studied:{textbook:[...studied.textbook],course:[...studied.course]},annotations:annotations.map(n=>({...n})),lastPage:snapshot()});return true}
function rememberPage(visit=false){if(!user||!ready||restoring)return;const p=snapshot();queueState({lastPage:p,...(visit?{visit:p}:{})})}
function retrySync(){if(!user)return;persist()}
function updateSyncLabel(){if($('#sync-label'))$('#sync-label').textContent=syncStatus;$('#storage-caption').textContent=user?(syncFailed?'学习记录未保存，请在账号页重试':'学习记录按账号同步保存'):'登录后同步你的学习记录'}
function accountBase(){return `<div class="page-top"><div><div class="eyebrow">MY ACCOUNT</div><h1>${esc(user.name)}的学习空间</h1><p class="muted">${isAdmin()?'课程管理员':'学生'} · ${esc(user.id)}</p></div></div><div class="panel"><h3>账号信息</h3><p class="muted">${isAdmin()?'你可以管理教材、课件和学生名单。':`班级：${esc(user.className||'未填写')}<br>浏览记录、收藏和掌握记录随账号保存。`}</p><div class="detail-actions"><a class="btn" href="#materials">${isAdmin()?'管理课程资料':'查看课程资料'}</a>${isAdmin()?'<a class="btn ghost" href="#students">学生名单</a>':''}<button class="btn ghost" onclick="retrySync()" id="sync-label">${syncStatus}</button><button class="btn ghost" onclick="logout()">退出登录</button></div></div><div class="section-head"><h2>最近浏览</h2><span class="muted">最近 ${history.length} 条</span></div><div class="chapter-list">${history.length?history.slice(0,30).map((v,i)=>`<button class="chapter" onclick="resumeHistory(${i})"><span class="chapter-num">${v.cardId!==null?'卡':'页'}</span><span class="chapter-info"><strong>${esc(v.cardId!==null?getCard(v.cardId)?.title||'知识卡片':({home:'学习首页',library:v.query?'检索：'+v.query:v.chapterFilter>=0?chapters[v.chapterFilter]:'知识库',map:'知识关系图',ask:'课程答疑',review:'复习',materials:'课程资料',course:course?.pages.find(p=>p.id===v.coursePage)?.title||'导入课件',textbook:textbook?.pages.find(p=>p.id===v.bookPage)?.label||'教材目录',document:(docs.find(d=>d.id===v.documentId)?.name||'上传资料')+' · 第 '+(v.documentPage||1)+' 页',account:'我的账号',students:'学生管理'}[v.route]||'学习页面'))}</strong><small>${new Date(v.at).toLocaleString('zh-CN',{hour12:false})}</small></span><span class="arrow">↗</span></button>`).join(''):'<div class="panel empty">开始浏览章节或卡片后，这里会出现你的学习足迹。</div>'}</div>`}
function resumeHistory(i){const v=history[i];if(!v)return;restoring=true;tab=v.route;coursePage=v.coursePage||null;bookPage=v.bookPage||null;activeDocument=v.documentId||null;documentPage=v.documentPage||1;query=v.query||'';chapterFilter=v.chapterFilter??-1;activeCard=null;window.history.replaceState(null,'','#'+tab);render();if(v.cardId!==null&&getCard(v.cardId))openCard(v.cardId);window.scrollTo(0,v.scroll||0);restoring=false;rememberPage(true)}
async function logout(){if(!user)return;await syncQueue;try{await api('/auth/logout',{method:'POST',body:'{}'});clearUser();ready=true;authMode='login';render();window.history.replaceState(null,'','#home');toast('已退出，学习记录保留在该账号下')}catch(err){toast(err.message)}}
function materials(){return pageHead('课程资料','管理员统一导入，登录后的学生可以查看和下载。','COURSE MATERIALS')+(isAdmin()?`<div class="upload-area"><div class="upload-icon">↥</div><h3>导入教材或老师课件</h3><p class="muted">支持 PDF、PPTX、TXT / Markdown 和图片，每份不超过 20 MB。<br>扫描页和图片先识别文字，再按页导入。旧版 PPT 请先另存为 PPTX。</p><label class="btn" for="upload" style="cursor:pointer">＋ 选择课程资料</label><input id="upload" type="file" accept=".pdf,.ppt,.pptx,.txt,.md,.jpg,.jpeg,.png,.webp" hidden onchange="importFile(event)"><p id="upload-status" class="muted" role="status" style="margin:12px 0 0"></p></div>`:'<div class="note">教材和课件由课程管理员统一上传。学生可以下载学习，不能导入或删除资料。</div>')+textbookSourceCard()+courseSourceCard()+`<div class="note">教材、课件和新上传资料均可按文字检索。黄色标记显示命中内容；自动识别的文字可能有误，请结合原文件核对。</div><div class="section-head"><h2>课程资料</h2><button class="text-link" onclick="refreshDocs()">刷新列表 ↻</button></div>${docs.length?docs.map(d=>`<div class="file-row"><span class="chapter-num">${/\.(txt|md)$/i.test(d.name)?'文':'课'}</span><div class="file-title"><strong>${esc(d.name)}</strong><small>${(d.size/1024).toFixed(1)} KB · ${d.pages?.length?d.pages.length+' 页 · 已建立检索索引':d.text?'支持文本检索':'待建立检索索引'}</small></div><button class="text-link" onclick="openDocument('${d.id}',1)">阅读</button><a class="text-link" href="/api/documents/${d.id}/download">下载</a>${isAdmin()&&!d.pages?.length?`<button class="text-link" onclick="reindexDocument('${d.id}')">建立索引</button>`:''}${isAdmin()?`<button class="danger" onclick="removeDoc('${d.id}')">移除</button>`:''}</div>`).join(''):'<div class="panel empty">管理员尚未上传课程资料。</div>'}`}
async function refreshDocs(){try{docs=(await api('/documents')).documents;render()}catch(err){toast(err.message)}}
async function legacyImportFile(e){if(!isAdmin()){toast('只有管理员可以导入资料');return}const f=e.target.files[0];if(!f)return;const form=new FormData();form.append('file',f);e.target.disabled=true;$('#upload-status').textContent='正在上传，请稍候…';try{await api('/documents',{method:'POST',body:form});docs=(await api('/documents')).documents;render();toast('课程资料已上传')}catch(err){if($('#upload-status'))$('#upload-status').textContent=err.message;toast(err.message)}finally{if($('#upload'))$('#upload').disabled=false}}
function removeDoc(id){if(!isAdmin())return;$('#detail-content').innerHTML=`<div class="dialog-top"><h2>移除这份课程资料？</h2><button class="close" aria-label="关闭" onclick="document.querySelector('#detail').close()">×</button></div><p class="muted">移除后，学生将无法再查看和下载。</p><div class="detail-actions"><button class="btn" onclick="confirmRemoveDoc('${id}')">确认移除</button><button class="btn ghost" onclick="document.querySelector('#detail').close()">取消</button></div>`;$('#detail').showModal()}
async function confirmRemoveDoc(id){try{await api('/documents/'+id,{method:'DELETE',body:'{}'});$('#detail').close();await refreshDocs();toast('资料已移除')}catch(err){toast(err.message)}}
function students(){if(!isAdmin())return '<div class="empty">只有管理员可以查看学生名单。</div>';return `<div class="page-top"><div><div class="eyebrow">STUDENT ACCOUNTS</div><h1>学生账号管理</h1><p class="muted">学号即账号，首次使用时核对姓名并设置密码。</p></div></div><div class="panel"><h3>本班学生名单</h3><p class="muted">当前 ${studentsList.length} 人 · 已设置密码 ${studentsList.filter(s=>s.activated).length} 人</p><button class="btn ghost" onclick="loadStudents()">刷新名单</button><a class="text-link" href="#account">返回账号页 ↗</a></div><div class="section-head"><h2>名单与激活状态</h2></div><div class="chapter-list">${studentsList.map(s=>`<div class="chapter"><span class="chapter-num">学</span><span class="chapter-info"><strong>${esc(s.name)} · ${esc(s.id)}</strong><small>${esc(s.className)}</small></span><span class="muted">${s.activated?'已设置密码':'待首次登录'}</span></div>`).join('')}</div>`}
async function loadStudents(){if(!isAdmin())return;try{studentsList=(await api('/admin/students')).students;if(tab==='students')render()}catch(err){toast(err.message)}}
function render(){if(!ready){$('#app').innerHTML='<div class="panel">正在载入账号和学习记录…</div>';return}if(!user){$('#app').innerHTML=authPage();$('#desktop-nav').innerHTML='';$('#mobile-nav').innerHTML='';$('#account-button').textContent='登';updateSyncLabel();return}if(tab==='students'&&!isAdmin())tab='account';const routes={home,library,map:graph,ask,review,materials,account,students,course:courseReader,textbook:textbookReader,document:documentReader};$('#app').innerHTML=(routes[tab]||home)();const items=[...navs,['account','◎','账号']];for(const sel of ['#desktop-nav','#mobile-nav'])$(sel).innerHTML=items.map(n=>`<a href="#${n[0]}" class="${tab===n[0]?'active':''}" ${tab===n[0]?'aria-current="page"':''}><span class="nav-symbol" aria-hidden="true">${n[1]}</span>${n[2]}</a>`).join('');$('#account-button').textContent=isAdmin()?'管':user.name.slice(-1);$('#account-button').title=isAdmin()?'管理员账号':'我的账号';updateSyncLabel();rememberPage(false);if(tab==='textbook'&&bookPage)loadTextbookImage(bookPage);if(!restoring&&query&&['course','textbook','document'].includes(tab))setTimeout(scrollToSearchHit,120)}
function route(){if(!ready||!user)return;activeCard=null;if($('#detail').open)$('#detail').close();tab=location.hash.slice(1)||'home';if(!['home','library','map','ask','review','materials','account','students','course','textbook','document'].includes(tab))tab='home';window.scrollTo(0,0);render();rememberPage(true);if(tab==='students')loadStudents();if(tab==='materials')refreshDocs()}
$('#detail').addEventListener('close',()=>{if(activeCard!==null){activeCard=null;rememberPage(false)}});
window.addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>rememberPage(false),600)},{passive:true});
window.addEventListener('pagehide',()=>{if(user&&ready&&!restoring)fetch('/api/state',{method:'PATCH',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json','X-Study-Request':'1'},body:JSON.stringify({userId:user.id,lastPage:snapshot()})}).catch(()=>{})});
function courseSourceCard(){if(!course)return '';return `<section class="panel course-source"><div><span class="category">${courseEnabled?'管理员导入 · 网页课件':'管理员已下架'}</span><h3 style="margin-top:12px">${esc(course.title)}</h3><p class="muted">${course.chapters.length} 个章节 · ${course.pages.length} 页 · 导入于 ${esc(course.importedAt)} · 管理员 ${esc(course.importedBy?.id||'课程管理员')}</p><p class="muted" style="margin-bottom:0">课件文字可阅读、检索；图示与交互动画请打开原版查看。</p></div><div class="detail-actions">${courseEnabled?'<button class="btn" onclick="startCourseReading()">阅读课件 ↗</button>':''}<a class="btn ghost" href="${esc(course.sourceUrl)}" target="_blank" rel="noopener noreferrer">打开原版</a>${isAdmin()?`<button class="btn ghost" onclick="setCourseVisibility(${!courseEnabled})">${courseEnabled?'下架课件':'重新上架'}</button>`:''}</div></section>`}
async function setCourseVisibility(enabled){if(!isAdmin())return;try{await api('/course',{method:enabled?'POST':'DELETE',body:'{}'});const result=await api('/course');course=result.course;courseEnabled=result.enabled;render();toast(enabled?'课件已上架':'课件已下架，学生不再可见')}catch(error){toast(error.message)}}
function courseHome(){if(!course||!courseEnabled)return exampleHome();return pageHead('沿着课程，系统学习。','从老师的课件出发，把每一页变成自己的理解。','YOUR LEARNING SPACE')+`<section class="hero"><div><div class="eyebrow">IMPORTED COURSE / 网页课件</div><h2>人工智能概论</h2><p>第一篇 · 人工智能概述<br>第二篇 · 人工智能基础</p><button class="btn light" onclick="startCourseReading()">开始阅读课件 <span>↗</span></button></div><div class="hero-graphic" aria-hidden="true"><i class="orbit"></i><i class="orbit"></i><i class="orbit"></i><span class="core">AI</span><i class="planet"></i><i class="planet"></i></div></section><div class="stats"><div class="stat"><div><div class="stat-label">导入章节</div><strong>${course.chapters.length}</strong> <small>章</small></div></div><div class="stat"><div><div class="stat-label">课件正文</div><strong>${course.pages.length}</strong> <small>页</small></div></div><div class="stat"><div><div class="stat-label">我的收藏</div><strong>${saved.length}</strong> <small>张卡片</small></div></div></div><div class="section-head"><h2>检索课程内容</h2><a class="text-link" href="#materials">课程资料 ↗</a></div>${searchHTML()}<div class="tags">${['图灵','机器学习','Transformer','大模型'].map(q=>`<button class="chip" onclick="quickSearch('${q}')">${q}</button>`).join('')}</div><div class="section-head"><h2>课程章节</h2><button class="text-link" onclick="openCourse(null)">全部 ${course.chapters.length} 章 ↗</button></div><div class="chapter-list">${course.chapters.slice(0,5).map(c=>chapterCourseHTML(c)).join('')}</div><div class="section-head"><h2>教材与课件知识卡片</h2><span class="muted">结合已导入资料整理</span></div><div class="knowledge-grid">${[6,8,10].map(i=>cardHTML(getCard(i))).join('')}</div><div class="note">课件文字已导入学习空间；图示、公式排版和动画请结合原版阅读。课件来源：<a href="${esc(course.sourceUrl)}" target="_blank" rel="noopener noreferrer">zhumy.github.io ↗</a></div>`}
function chapterCourseHTML(c){const pages=course.pages.filter(p=>p.chapterId===c.id);return `<button class="chapter" onclick="openCourse('${pages[0]?.id||course.pages[0].id}')"><span class="chapter-num">${String(c.number).padStart(2,'0')}</span><span class="chapter-info"><strong>${esc(c.title)}</strong><small>第${c.part===1?'一':'二'}篇 · ${pages.length} 页课件</small></span><span class="arrow">↗</span></button>`}
function startCourseReading(){const first=course?.pages?.[0];if(!first){toast('课件暂无可阅读页面，请联系管理员');return}openCourse(first.id)}
function openCourse(id){pendingExcerpt="";if(!user||!courseEnabled||!course)return;coursePage=id&&course.pages.some(p=>p.id===id)?id:null;activeCard=null;if($('#detail').open)$('#detail').close();if(tab==='course'){window.scrollTo(0,0);render();rememberPage(true)}else location.hash='course'}
function courseReader(){if(!course||!courseEnabled)return pageHead('课程课件','该课件暂不可用，请联系管理员。','COURSE READER');const p=course.pages.find(p=>p.id===coursePage);if(!p)return pageHead(course.title,'按章节阅读导入内容，随时跳转到原课件。','COURSE READER')+courseSourceCard()+`<div class="section-head"><h2>课件导读</h2></div><div class="chapter-list">${course.pages.filter(p=>!p.chapterId).map(p=>`<button class="chapter" onclick="openCourse('${p.id}')"><span class="chapter-num">序</span><span class="chapter-info"><strong>${esc(p.title)}</strong><small>导读 · 第 ${p.number} 页</small></span><span class="arrow">↗</span></button>`).join('')}</div>${[1,2].map(part=>`<div class="section-head"><h2>第${part===1?'一':'二'}篇 · ${part===1?'人工智能概述':'人工智能基础'}</h2></div><div class="chapter-list">${course.chapters.filter(c=>c.part===part).map(chapterCourseHTML).join('')}</div>`).join('')}`;const index=course.pages.indexOf(p),chapter=course.chapters.find(c=>c.id===p.chapterId),chapterPages=course.pages.filter(x=>x.chapterId===p.chapterId);return `<div class="reader-top"><button class="text-link" onclick="openCourse(null)">← 课程目录</button><span class="muted">课件第 ${p.number} / ${course.pages.length} 页</span></div><div class="eyebrow">${chapter?'CHAPTER '+String(chapter.number).padStart(2,'0'):'COURSE OVERVIEW'}</div><h1>${esc(p.title)}</h1><p class="muted">${chapter?esc(chapter.title):'课程导读'} · 课件原文摘取</p><label class="reader-select-label" for="course-page-select">本节页面<select id="course-page-select" onchange="openCourse(this.value)">${chapterPages.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${x.number}. ${esc(x.title)}</option>`).join('')}</select></label><article class="panel course-body">${highlightHtml(p.html)}</article><div class="note">来源：<a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">原课件本页 ↗</a>${p.hasVisuals?' · 本页含图示或动画，请结合原版查看。':' · 导入内容保留原文，未进行事实核验。'}</div>${readerStudyPanel('course',p.id)}<div class="reader-pagination"><button class="btn ghost" ${index===0?'disabled':''} onclick="openCourse('${course.pages[Math.max(0,index-1)].id}')">← 上一页</button><a class="text-link" href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">查看原版</a><button class="btn" ${index===course.pages.length-1?'disabled':''} onclick="openCourse('${course.pages[Math.min(course.pages.length-1,index+1)].id}')">下一页 →</button></div>`}
function findCoursePages(q){if(!course||!courseEnabled||!q.trim())return [];const normalized=q.trim().toLowerCase();const keywords=[normalized,...(normalized.match(/人工智能|机器学习|深度学习|监督学习|无监督学习|强化学习|神经网络|神经元|反向传播|图灵|达特茅斯|梯度下降|过拟合|大模型|transformer|gpt|agent|skill|harness|多模态|学习策略/g)||[])];return course.pages.map(p=>{const text=p.text.toLowerCase(),title=p.title.toLowerCase();const terms=[...new Set(keywords)].filter(k=>k&&text.includes(k));if(!terms.length)return null;const first=terms.find(t=>text.includes(t));const at=text.indexOf(first);const chapter=course.chapters.find(c=>c.id===p.chapterId);return {...p,name:(chapter?'第 '+chapter.number+' 章 · ':'')+p.title,snippet:p.text.slice(Math.max(0,at-45),at+200),score:terms.reduce((sum,k)=>sum+(title.includes(k)?8:1),0)}}).filter(Boolean).sort((a,b)=>b.score-a.score||a.number-b.number)}
function courseSearchDocs(q){return [...findCoursePages(q).map(p=>({id:p.id,name:p.name,text:p.text,snippet:p.snippet,coursePage:p.id,pageNumber:p.number})),...fileSearchDocs(q)]}

let textbookKey=null,imageSerial=0;
const textbookImageUrls=new Map();
function resetTextbookImages(){textbookKey=null;imageSerial++;for(const url of textbookImageUrls.values())URL.revokeObjectURL(url);textbookImageUrls.clear()}
function textbookSourceCard(){if(!textbook)return '';const stat=textbook.compression;return `<section class="panel course-source textbook-source"><div><span class="category">${textbookEnabled?'管理员导入 · 图片教材':'教材已下架'}</span><h3 style="margin-top:12px">《${esc(textbook.title)}》</h3><p class="muted">${textbook.pages.length} 张图片 · 按印刷页码排序 · 管理员 ${esc(textbook.importedBy.id)}</p><p class="muted" style="margin-bottom:0">已压缩约 ${Math.round((1-stat.compressedBytes/stat.originalBytes)*100)}%，支持教材文字检索。重复照片保留为同页备用图。</p></div><div class="detail-actions">${textbookEnabled?'<button class="btn" onclick="openTextbook(null)">阅读教材 ↗</button><button class="btn ghost" onclick="quickSearch(\'人工智能\')">检索教材与课件</button>':''}${isAdmin()?`<button class="btn ghost" onclick="setTextbookVisibility(${!textbookEnabled})">${textbookEnabled?'下架教材':'重新上架'}</button>`:''}</div></section>`}
async function setTextbookVisibility(enabled){if(!isAdmin())return;try{await api('/textbook',{method:enabled?'POST':'DELETE',body:'{}'});const r=await api('/textbook');textbook=r.textbook;textbookEnabled=r.enabled;if(!enabled)resetTextbookImages();render();toast(enabled?'教材已上架':'教材已下架')}catch(error){toast(error.message)}}
function home(){const h=courseHome();if(!textbook||!textbookEnabled)return h;const marker='<div class="section-head"><h2>检索课程内容';return h.includes(marker)?h.replace(marker,textbookSourceCard()+marker):textbookSourceCard()+h}
function openTextbook(id){pendingExcerpt="";if(!user||!textbookEnabled||!textbook)return;bookPage=id&&textbook.pages.some(p=>p.id===id)?id:null;activeCard=null;if($('#detail').open)$('#detail').close();if(tab==='textbook'){window.scrollTo(0,0);render();rememberPage(true)}else location.hash='textbook'}
function textbookReader(){if(!textbook||!textbookEnabled)return pageHead('教材','教材暂不可用，请联系管理员。','TEXTBOOK');const p=textbook.pages.find(p=>p.id===bookPage);if(!p){const groups=[...new Set(textbook.pages.map(p=>p.group))];return pageHead('按页码，阅读教材。','封面、前置资料与正文已分组；同页重复照片作为备用图保留。','TEXTBOOK LIBRARY')+textbookSourceCard()+groups.map(group=>`<div class="section-head"><h2>${esc(group)}</h2></div><div class="chapter-list">${textbook.pages.filter(p=>p.group===group).map(p=>`<button class="chapter" onclick="openTextbook('${p.id}')"><span class="chapter-num">${esc(p.shortLabel)}</span><span class="chapter-info"><strong>${esc(p.label)}</strong><small>${esc(p.title)}${p.alternate?' · 备用图':''}</small></span><span class="arrow">↗</span></button>`).join('')}</div>`).join('')};const index=textbook.pages.indexOf(p);return `<div class="reader-top"><button class="text-link" onclick="openTextbook(null)">← 教材目录</button><span class="muted">图片 ${index+1} / ${textbook.pages.length}</span></div><div class="eyebrow">TEXTBOOK / 管理员导入</div><h1>${esc(p.label)}</h1><p class="muted">${esc(p.title)} · ${esc(textbook.title)}</p><label class="reader-select-label" for="book-page-select">跳转页码<select id="book-page-select" onchange="openTextbook(this.value)">${textbook.pages.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.label)} · ${esc(x.title)}</option>`).join('')}</select></label><div class="panel textbook-image-wrap"><p id="book-image-status" class="muted" role="status">正在载入本页图片…</p><div class="textbook-image-stage"><img id="book-image" alt="${esc(p.label)}：${esc(p.title)}" width="${p.width}" height="${p.height}" hidden><div id="book-hit-overlay" class="book-hit-overlay" hidden>${bookImageHighlights(p)}</div></div><a id="book-zoom" class="text-link" hidden target="_blank" rel="noopener">放大阅读 ↗</a></div><details class="panel textbook-text"><summary>查看本页识别文字</summary><p class="muted">文字由图片自动识别，可能包含错字，公式与图表请以教材图片为准。</p><div>${esc(p.text||'本页未识别到可检索文字，请直接查看图片。').replace(/\n/g,'<br>')}</div></details>${readerStudyPanel('textbook',p.id)}<div class="reader-pagination"><button class="btn ghost" ${index===0?'disabled':''} onclick="openTextbook('${textbook.pages[Math.max(0,index-1)].id}')">← 上一页</button><button class="text-link" onclick="quickSearch('${esc(p.title.replace(/['"<>]/g,''))}')">查找相关内容</button><button class="btn" ${index===textbook.pages.length-1?'disabled':''} onclick="openTextbook('${textbook.pages[Math.min(textbook.pages.length-1,index+1)].id}')">下一页 →</button></div>`}
async function loadTextbookImage(id){const serial=++imageSerial,owner=user?.id,p=textbook?.pages.find(p=>p.id===id);if(!p||!owner)return;const current=()=>user?.id===owner&&serial===imageSerial&&tab==='textbook'&&bookPage===id;try{let url=textbookImageUrls.get(id);if(!url){if(!textbookKey){const result=await api('/textbook/image-key');if(!current())return;const bytes=new Uint8Array(result.key.match(/.{2}/g).map(x=>parseInt(x,16)));textbookKey=await crypto.subtle.importKey('raw',bytes,'AES-GCM',false,['decrypt'])}if(!current())return;const response=await fetch(p.assetUrl);if(!response.ok)throw Error('教材图片暂时无法读取');const bytes=new Uint8Array(await response.arrayBuffer());if(!current())return;const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes.slice(0,12)},textbookKey,bytes.slice(12));if(!current())return;url=URL.createObjectURL(new Blob([plain],{type:'image/webp'}));textbookImageUrls.set(id,url);while(textbookImageUrls.size>2){const oldest=textbookImageUrls.keys().next().value;URL.revokeObjectURL(textbookImageUrls.get(oldest));textbookImageUrls.delete(oldest)}}if(!current())return;const img=$('#book-image');img.src=url;img.hidden=false;if($('#book-hit-overlay'))$('#book-hit-overlay').hidden=false;$('#book-zoom').href=url;$('#book-zoom').hidden=false;$('#book-image-status').textContent='本页已压缩，可放大阅读。'}catch(error){if(current()&&$('#book-image-status'))$('#book-image-status').innerHTML=esc(error.message)+' <button class="text-link" onclick="loadTextbookImage(\''+id+'\')">重试</button>'}}
function findTextbookPages(q){if(!textbook||!textbookEnabled||!q.trim())return [];const normalize=s=>s.toLowerCase().replace(/\s+/g,'');const normalized=normalize(q),words=[normalized,...(normalized.match(/人工智能|机器学习|深度学习|监督学习|无监督学习|强化学习|神经网络|神经元|反向传播|图灵|梯度下降|过拟合|大模型|transformer|gpt|机器人|卷积|感知器|知识图谱|语音识别/g)||[])];return textbook.pages.filter(p=>!p.alternate).map(p=>{const text=normalize(p.text),title=normalize(p.title),terms=[...new Set(words)].filter(k=>k&&text.includes(k));if(!terms.length)return null;const term=terms[0],at=p.text.toLowerCase().indexOf(term);return {...p,snippet:p.text.slice(Math.max(0,at-45),Math.max(0,at)+210),score:terms.reduce((n,k)=>n+(title.includes(k)?8:1),0)}}).filter(Boolean).sort((a,b)=>b.score-a.score||a.order-b.order)}
function searchDocs(q){return [...findTextbookPages(q).map(p=>({id:p.id,name:'《'+textbook.title+'》 · '+p.label+' · '+p.title,text:p.text,snippet:p.snippet,bookPage:p.id,printLabel:p.label})),...courseSearchDocs(q)]}

function getSearchTerms(value=query){return [...new Set([value.trim(),...(value.toLowerCase().match(/人工智能|机器学习|深度学习|监督学习|无监督学习|强化学习|神经网络|神经元|反向传播|图灵|梯度下降|过拟合|大模型|transformer|gpt|机器人|卷积|感知器|知识图谱|语音识别/g)||[])])].filter(Boolean).sort((a,b)=>b.length-a.length)}
function highlightText(value){const text=String(value),positions=[],ranges=[];let lower='';for(let i=0;i<text.length;i++)if(!/\s/.test(text[i])){const folded=text[i].toLowerCase();lower+=folded;for(let j=0;j<folded.length;j++)positions.push(i)}for(const term of getSearchTerms()){const needle=term.toLowerCase().replace(/\s+/g,'');if(!needle)continue;let i=0;while((i=lower.indexOf(needle,i))>=0){ranges.push([positions[i],positions[i+needle.length-1]+1]);i+=needle.length}}if(!ranges.length)return esc(text);ranges.sort((a,b)=>a[0]-b[0]||b[1]-a[1]);const merged=[];for(const range of ranges){const last=merged[merged.length-1];if(last&&range[0]<=last[1])last[1]=Math.max(last[1],range[1]);else merged.push([...range])}let result='',from=0;for(const [a,b] of merged){result+=esc(text.slice(from,a))+'<mark class="search-hit">'+esc(text.slice(a,b))+'</mark>';from=b}return result+esc(text.slice(from))}
function highlightHtml(html){const decode=t=>t.replace(/&(amp|lt|gt|quot|#39|#\d+|#x[0-9a-f]+);/gi,(m,v)=>({amp:'&',lt:'<',gt:'>',quot:'"','#39':"'"}[v]??String.fromCodePoint(v.toLowerCase().startsWith('#x')?parseInt(v.slice(2),16):parseInt(v.slice(1),10))));return html.split(/(<[^>]+>)/g).map(part=>part.startsWith('<')?part:highlightText(decode(part))).join('')}
function bookImageHighlights(p){return ''}
function scrollToSearchHit(){const hit=$('.ebook-prose .search-hit')||$('.book-hit')||$('.course-body .search-hit')||$('.document-body .search-hit');if(hit&&typeof hit.scrollIntoView==='function')hit.scrollIntoView({block:'center',behavior:'smooth'})}
function fileSearchDocs(q){if(!q.trim())return [];const terms=getSearchTerms(q).map(t=>t.toLowerCase().replace(/\s+/g,''));return docs.flatMap(d=>{const pages=d.pages?.length?d.pages:[{pageNumber:1,title:d.name,text:d.text||''}];const hits=pages.filter(p=>terms.some(t=>p.text.toLowerCase().replace(/\s+/g,'').includes(t)));const selected=hits.length?hits:d.name.toLowerCase().includes(q.toLowerCase())?[pages[0]]:[];return selected.map(p=>{const term=terms.find(t=>p.text.toLowerCase().includes(t));const at=term?p.text.toLowerCase().indexOf(term):0;return {id:d.id,name:d.name+' · 第 '+p.pageNumber+' 页',snippet:p.text.slice(Math.max(0,at-45),at+200)||'文件名匹配。本页未识别到文字，可查看原文件。',documentId:d.id,pageNumber:p.pageNumber}})})}
async function importFile(e){if(!isAdmin())return;const file=e.target.files[0];if(!file)return;e.target.disabled=true;const progress=text=>{if($('#upload-status'))$('#upload-status').textContent=text};try{const {extractDocument}=await import('/document-import.mjs');const extracted=await extractDocument(file,progress);progress('正在上传并保存检索索引…');const form=new FormData();form.append('file',extracted.file);form.append('index',JSON.stringify(extracted.pages));await api('/documents',{method:'POST',body:form});docs=(await api('/documents')).documents;render();toast('资料和检索索引已保存')}catch(error){progress('未导入：'+error.message);toast(error.message)}finally{if($('#upload'))$('#upload').disabled=false}}
async function reindexDocument(id){if(!isAdmin())return;const d=docs.find(d=>d.id===id);if(!d)return;toast('正在为已有资料建立索引，请保持页面打开');try{const response=await fetch('/api/documents/'+id+'/download');if(!response.ok)throw Error('无法读取原文件');const file=new File([await response.blob()],d.name,{type:d.mime});const {extractDocument}=await import('/document-import.mjs');const result=await extractDocument(file,text=>toast(text));await api('/documents/'+id+'/index',{method:'PATCH',body:JSON.stringify({pages:result.pages})});await refreshDocs();toast('资料已纳入按页检索')}catch(error){toast('索引未完成：'+error.message)}}
function openDocument(id,pageNumber){if(!user||!docs.some(d=>d.id===id))return;activeDocument=id;documentPage=pageNumber;activeCard=null;if($('#detail').open)$('#detail').close();if(tab==='document'){window.scrollTo(0,0);render();rememberPage(true)}else location.hash='document'}
function documentReader(){const d=docs.find(d=>d.id===activeDocument);if(!d)return pageHead('上传资料','资料不存在或已经移除。','UPLOADED MATERIAL');const pages=d.pages?.length?d.pages:[{pageNumber:1,title:d.name,text:d.text||'',method:'text'}];const p=pages.find(p=>p.pageNumber===documentPage)||pages[0];documentPage=p.pageNumber;const original='/api/documents/'+d.id+'/download?inline=1#page='+p.pageNumber;return `<div class="reader-top"><a class="text-link" href="#materials">← 课程资料</a><span class="muted">第 ${p.pageNumber} / ${pages.length} 页</span></div><div class="eyebrow">ADMINISTRATOR UPLOAD</div><h1>${esc(d.name)}</h1><p class="muted">管理员上传 · 第 ${p.pageNumber} 页 · ${p.method==='ocr'?'包含自动识别文字':'提取文字'}</p><label class="reader-select-label" for="document-page-select">跳转页码<select id="document-page-select" onchange="openDocument('${d.id}',Number(this.value))">${pages.map(x=>`<option value="${x.pageNumber}" ${x.pageNumber===p.pageNumber?'selected':''}>第 ${x.pageNumber} 页 · ${esc(x.title)}</option>`).join('')}</select></label>${/\.(png|jpe?g|webp)$/i.test(d.name)?`<div class="panel textbook-image-wrap"><img src="${original}" alt="${esc(d.name)}"></div>`:''}<article class="panel document-body course-body">${highlightText(p.text||'本页没有可提取文字，请打开原文件查看。').replace(/\n/g,'<br>')}</article><div class="note">黄色标记为匹配内容。自动识别可能有错字，请结合原文件核对。${!d.pages?.length?' 此资料尚未完成分页索引，管理员可在课程资料页建立索引。':''}</div><div class="reader-pagination"><button class="btn ghost" ${p.pageNumber===1?'disabled':''} onclick="openDocument('${d.id}',${Math.max(1,p.pageNumber-1)})">← 上一页</button><a class="text-link" href="${original}" target="_blank" rel="noopener noreferrer">打开原文件 ↗</a><button class="btn" ${p.pageNumber===pages.length?'disabled':''} onclick="openDocument('${d.id}',${Math.min(pages.length,p.pageNumber+1)})">下一页 →</button></div>`}

let mapNode='book',mapRelation='all',mapSearch='';
let studied={textbook:[],course:[]},reviewFilter='all',reviewQuestion=null,reviewRevealed=false,reviewSeen=[];
function activeGraph(){return textbookEnabled?textbook?.knowledgeGraph:null}
function mapPageButtons(pages,nodeId){return [...new Set(pages)].map(n=>`<button class="source-link" onclick="openMapPage(${n},'${nodeId}')">教材第 ${n} 页 ↗</button>`).join('')}
function openMapPage(number,id){const graph=activeGraph(),node=graph?.nodes.find(n=>n.id===id),page=textbook?.pages.find(p=>p.pageNumber===number&&p.printedPage&&!p.alternate);if(!page)return;query=node?.label||'';openTextbook(page.id)}
function focusMap(id){if(!activeGraph()?.nodes.some(n=>n.id===id))return;mapNode=id;mapSearch='';render();$('#map-detail')?.scrollIntoView?.({block:'start',behavior:'smooth'})}
function mapSearchResults(value){const graph=activeGraph();if(!value.trim())return '';const needle=value.trim().toLowerCase();const found=graph.nodes.filter(n=>(n.label+' '+n.summary).toLowerCase().includes(needle));return found.length?found.map(n=>`<button class="map-search-result" onclick="focusMap('${n.id}')"><strong>${esc(n.label)}</strong><small>${n.pages.map(p=>'第 '+p+' 页').join('、')} ↗</small></button>`).join(''):'<p class="muted">未找到概念，试试“卷积”“强化学习”或“风险”。</p>'}
function searchMap(value){mapSearch=value;$('#map-search-results').innerHTML=mapSearchResults(value)}
function setMapRelation(value){mapRelation=value;render()}
function graph(){const g=activeGraph();if(!g)return pageHead('教材关系图','教材暂不可用，请联系管理员。','TEXTBOOK KNOWLEDGE MAP')+'<div class="panel empty">教材上架后可查看关系图。</div>';const selected=g.nodes.find(n=>n.id===mapNode)||g.nodes[0];mapNode=selected.id;const all=g.edges.filter(e=>e.from===mapNode||e.to===mapNode),links=all.filter(e=>mapRelation==='all'||e.type===mapRelation);const neighbors=[...new Set(links.map(e=>e.from===mapNode?e.to:e.from))];const visible=neighbors.slice(0,8);const rowHeight=112,height=Math.max(220,visible.length*rowHeight+30);const cx=105,cy=height/2;const part=g.parts.find(p=>p.id==='part'+selected.part);return pageHead('把知识，连成一张图。','依据《人工智能通识》的目录与正文整理；选择概念，查看联系并回到教材。','TEXTBOOK KNOWLEDGE MAP')+`<div class="map-meta"><span>${g.nodes.length} 个主题与概念</span><span>${g.edges.length} 条关系</span><span>覆盖 4 篇 · 51 节</span></div><div class="tags map-tabs"><button class="chip ${mapNode==='book'?'active':''}" onclick="focusMap('book')">全书总览</button>${g.parts.map(p=>`<button class="chip ${selected.part===Number(p.id.slice(4))?'active':''}" onclick="focusMap('${p.id}')">${esc(p.label)}</button>`).join('')}</div><label class="map-search-label">查找教材概念<input id="map-search" type="search" value="${esc(mapSearch)}" placeholder="例如：自注意力、机器学习、人脸识别" oninput="searchMap(this.value)"></label><div id="map-search-results" class="map-search-results" aria-live="polite">${mapSearchResults(mapSearch)}</div><section class="panel map-detail" id="map-detail"><div class="eyebrow">${part?esc(part.label):'全书结构'}</div><h2>${esc(selected.label)}</h2><p class="muted">${esc(selected.summary)}</p><div class="map-sources">${mapPageButtons(selected.pages,selected.id)}</div><div class="tags"><button class="chip ${mapRelation==='all'?'active':''}" onclick="setMapRelation('all')">全部关系</button><button class="chip ${mapRelation==='outline'?'active':''}" onclick="setMapRelation('outline')">目录与概念</button><button class="chip ${mapRelation==='concept'?'active':''}" onclick="setMapRelation('concept')">方法与应用</button></div><p class="muted map-instruction">点击节点展开。箭头表示下方标注的关系方向。</p>${visible.length?`<div class="map-canvas">${mobileMapDiagram(selected,visible,links,g)}<svg viewBox="0 0 640 ${height}" role="group" aria-label="${esc(selected.label)}的教材关系图"><defs><marker id="map-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#8aa07c"/></marker></defs>${visible.map((id,i)=>{const n=g.nodes.find(n=>n.id===id),e=links.find(e=>e.from===id||e.to===id),y=20+i*rowHeight;return `<path d="M190 ${cy}C285 ${cy} 265 ${y+30} 365 ${y+30}" fill="none" stroke="${e.type==='outline'?'#bdcbb3':'#7f9c83'}" stroke-width="1.5" ${e.from===mapNode?'marker-end':'marker-start'}="url(#map-arrow)"/><text x="270" y="${y+18}" font-size="12" fill="#65775d">${esc(e.label)}</text><g role="button" tabindex="0" aria-label="展开${esc(n.label)}" onclick="focusMap('${id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();focusMap('${id}')}"><rect x="367" y="${y}" width="257" height="62" rx="12" fill="#f2f5eb" stroke="#d6dfcc"/><text x="495" y="${y+28}" text-anchor="middle" font-size="${n.label.length>12?12:14}" fill="#365842">${esc(n.label)}</text><text x="495" y="${y+47}" text-anchor="middle" font-size="11" fill="#7a8970">${n.kind==='part'?'展开本篇':n.pages.map(p=>'P'+p).join(' · ')} ↗</text></g>`}).join('')}<rect x="12" y="${cy-38}" width="178" height="76" rx="14" fill="#244d39"/><text x="101" y="${cy+5}" fill="white" text-anchor="middle" font-size="${selected.label.length>10?12:15}">${esc(selected.label)}</text></svg></div>`:'<div class="empty">当前筛选下没有直接关系，请切换“全部关系”。</div>'}${neighbors.length>8?`<p class="muted">图中显示前 8 个相邻节点，下方列出全部 ${links.length} 条关系。</p>`:''}</section><div class="section-head"><h2>关系与教材依据</h2><span class="muted">${links.length} 条</span></div><div class="map-relations">${links.map(e=>{const from=g.nodes.find(n=>n.id===e.from),to=g.nodes.find(n=>n.id===e.to);return `<article class="panel"><div class="map-triple"><button onclick="focusMap('${from.id}')">${esc(from.label)}</button><span>— ${esc(e.label)} →</span><button onclick="focusMap('${to.id}')">${esc(to.label)}</button></div><div class="map-sources">${mapPageButtons(e.pages,selected.id)}</div></article>`}).join('')||'<div class="panel empty">可切换关系类型继续探索。</div>'}</div><div class="section-head"><h2>建议学习顺序</h2></div><p class="muted">按知识衔接整理的学习建议，可按需要跳读。</p>${g.paths.map(path=>`<section class="panel map-path"><h3>${esc(path.label)}</h3><div>${path.nodes.map((id,i)=>`<button class="chip" onclick="focusMap('${id}')">${i+1}. ${esc(g.nodes.find(n=>n.id===id).label)}</button>`).join('<span aria-hidden="true"> → </span>')}</div></section>`).join('')}`}
function studyButton(kind,id){const done=studied[kind].includes(id);return `<section class="panel study-panel"><div><strong>${done?'✓ 本页已学习':'读完这一页了吗？'}</strong><p class="muted">${done?'本页已加入你的复习范围。':'标记后，复习将从本页内容中提问。'}</p></div><div class="detail-actions"><button class="btn ${done?'ghost':''}" aria-pressed="${done}" onclick="toggleStudied('${kind}','${id}')">${done?'✓ 已学习 · 点击撤销':'标记为已学习'}</button>${done?'<a class="text-link" href="#review">去复习 ↗</a>':''}</div></section>`}
function resetReview(){reviewQuestion=null;reviewRevealed=false;reviewSeen=[]}
function toggleStudied(kind,id){if(!user||!['textbook','course'].includes(kind))return;const source=kind==='textbook'?textbook:course;if(!source?.pages.some(p=>p.id===id))return;const done=studied[kind].includes(id);studied[kind]=done?studied[kind].filter(x=>x!==id):[...studied[kind],id];resetReview();persist();render();toast(done?'本页已移出复习范围':'本页已学习，已加入复习范围')}
function studiedPages(){return [...(textbookEnabled&&textbook?textbook.pages.filter(p=>studied.textbook.includes(p.id)).map(p=>({...p,kind:'textbook',sourceLabel:'教材 · '+p.label})):[]),...(courseEnabled&&course?course.pages.filter(p=>studied.course.includes(p.id)).map(p=>({...p,kind:'course',sourceLabel:'课件 · 第 '+p.number+' 页'})):[])].filter(p=>reviewFilter==='all'||p.kind===reviewFilter)}
function makeReviewQuestions(){const vocabulary=[...(textbook?.knowledgeGraph?.nodes.filter(n=>n.kind==='concept').map(n=>n.label)||[]),'人工智能','机器学习','深度学习','神经网络','监督学习','无监督学习','强化学习','知识图谱','专家系统','梯度下降','过拟合','自注意力','注意力机制','Transformer','CNN','RNN','GAN','图灵测试','图灵机','达特茅斯会议','卷积核','卷积神经网络','循环神经网络','大语言模型','语言模型','词向量','自监督学习','扩散模型','对抗样本','可解释性','生成器','判别器','训练集','测试集','模型参数','目标函数','倒排索引','路径规划','蒙特卡洛','残差网络','特征提取','高级特征','多模态','自编码器','感知器','损失函数','反向传播','提示词','思维链','隐私','知识表示','搜索','推理','数据'];const terms=[...new Set(vocabulary)].sort((a,b)=>b.length-a.length);const questions=[];for(const p of studiedPages()){if(p.kind==='textbook'&&(!p.printedPage||p.alternate&&p.text.length<70))continue;const text=p.text.replace(/[ \t]+/g,' ').trim(),lines=text.split(/(?<=[。！？；])|\n/).map(s=>s.trim()).filter(s=>s.length>=20&&s.length<=240&&!/思考与讨论|实践设计|视频资源|参考文献|版权|估计值/.test(s));const candidates=[];for(const line of lines){const term=terms.find(t=>line.toLowerCase().includes(t.toLowerCase())&&line.replaceAll(t,'').length>16);if(!term)continue;const at=line.toLowerCase().indexOf(term.toLowerCase());const answer=line.slice(at,at+term.length);const prompt=line.slice(0,at)+'【　　　】'+line.slice(at+term.length);candidates.push({id:p.kind+':'+p.id+':'+candidates.length,kind:p.kind,pageId:p.id,sourceLabel:p.sourceLabel,prompt,answer,original:line});if(candidates.length===3)break}questions.push(...candidates)}return questions}
function setReviewFilter(filter){reviewFilter=filter;resetReview();render()}
function nextReview(){const bank=makeReviewQuestions(),remaining=bank.filter(q=>!reviewSeen.includes(q.id));if(!bank.length)return;if(!remaining.length)reviewSeen=[];const pool=remaining.length?remaining:bank;reviewQuestion=pool[Math.floor(Math.random()*pool.length)];reviewSeen.push(reviewQuestion.id);reviewRevealed=false;render()}
function checkReview(e){e.preventDefault();if(!reviewQuestion)return;const answer=e.target.elements.answer.value.trim();reviewRevealed=true;const normalize=s=>s.toLowerCase().replace(/[\s\p{P}\p{S}]/gu,'');reviewQuestion={...reviewQuestion,attempt:answer,correct:answer?normalize(answer)===normalize(reviewQuestion.answer):null};render()}
function revealReview(){if(!reviewQuestion)return;reviewRevealed=true;render()}
function returnReviewSource(){if(!reviewQuestion)return;query=reviewQuestion.answer;if(reviewQuestion.kind==='textbook')openTextbook(reviewQuestion.pageId);else openCourse(reviewQuestion.pageId)}
function review(){const pages=studiedPages(),bank=makeReviewQuestions();if(reviewQuestion&&!bank.some(q=>q.id===reviewQuestion.id)){reviewQuestion=null;reviewRevealed=false}const q=reviewQuestion;return pageHead('从学过的内容，检验理解。','只从你标记为“已学习”的教材和课件页面中提问。','REVIEW WHAT YOU LEARNED')+`<div class="panel review-scope"><div><span class="eyebrow">我的复习范围</span><h2>${pages.length} 页已学习</h2><p class="muted">教材 ${textbookEnabled?studied.textbook.length:0} 页 · 课件 ${courseEnabled?studied.course.length:0} 页</p></div><div class="tags"><button class="chip ${reviewFilter==='all'?'active':''}" onclick="setReviewFilter('all')">全部</button><button class="chip ${reviewFilter==='textbook'?'active':''}" onclick="setReviewFilter('textbook')">只练教材</button><button class="chip ${reviewFilter==='course'?'active':''}" onclick="setReviewFilter('course')">只练课件</button></div></div>${!pages.length?`<div class="panel empty"><h3>先阅读，再开始复习</h3><p>读完教材或课件后，点击页面下方的“标记为已学习”。</p><div class="detail-actions"><button class="btn" onclick="openTextbook(null)">阅读教材</button><button class="btn ghost" onclick="startCourseReading()">阅读课件</button></div></div>`:!bank.length?'<div class="panel empty">这些页面暂未提取到适合出题的完整文字。可以继续学习正文页，或返回原页自行回顾；不会从未学习的内容出题。</div>':`<section class="panel review-exercise"><div class="review-question-top"><span class="category">概念填空 · 原文回忆</span><span class="muted">本轮 ${reviewSeen.length} / ${bank.length}</span></div>${q?`<p class="muted">出题范围：${esc(q.sourceLabel)}</p><h2>这段话中缺少哪个概念？</h2><blockquote>${esc(q.prompt)}</blockquote>${!reviewRevealed?`<form onsubmit="checkReview(event)" class="review-answer"><label for="review-answer">你的答案</label><input id="review-answer" name="answer" maxlength="120" autocomplete="off" placeholder="先回忆，再看答案"><div class="detail-actions"><button class="btn" type="submit">核对答案</button><button class="btn ghost" type="button" onclick="revealReview()">查看答案</button></div></form>`:`<div class="review-feedback" role="status"><strong>${q.correct===true?'✓ 回答正确':q.correct===false?'再回顾一下这个概念':'参考答案'}</strong><p>缺少的概念：<b>${esc(q.answer)}</b></p>${q.attempt?`<p class="muted">你的答案：${esc(q.attempt)}</p>`:''}<p>${esc(q.original)}</p><small class="muted">按原文关键词核对，同义表达可自行对照。识别文字可能有误，请以原页为准。</small><div class="detail-actions"><button class="text-link" onclick="returnReviewSource()">返回原页核对 ↗</button><button class="btn" onclick="nextReview()">下一题 →</button></div></div>`}`:`<h2>把刚学过的知识，回忆一次。</h2><p class="muted">当前可生成 ${bank.length} 道原文概念填空；先尝试作答，再核对原文。</p><button class="btn" onclick="nextReview()">开始复习 ↗</button>`}</section>`}${pages.length?`<details class="panel review-page-list"><summary>查看本次复习范围（${pages.length} 页）</summary>${pages.map(p=>`<div><button class="text-link" onclick="${p.kind==='textbook'?'openTextbook':'openCourse'}('${p.id}')">${esc(p.sourceLabel)} · ${esc(p.title)}</button><button class="text-link" onclick="toggleStudied('${p.kind}','${p.id}')" aria-label="移出${esc(p.sourceLabel)}">移出</button></div>`).join('')}</details>`:''}<div class="section-head"><h2>收藏的知识卡片</h2></div><div class="knowledge-grid">${saved.map(id=>getCard(id)).filter(Boolean).map(cardHTML).join('')||'<p class="muted">暂无收藏。收藏卡片可辅助回顾，不会扩大上方的出题范围。</p>'}</div>`}

let annotations=[],annotationFilter='all',showAnnotations=false,showFavorites=false;
function pageAnnotation(kind,id){return annotations.find(n=>n.kind===kind&&n.pageId===id)}
function readerStudyPanel(kind,id){const n=pageAnnotation(kind,id)||{important:false,difficult:false,note:'',excerpt:''};return studyButton(kind,id)+`<section class="panel annotation-editor"><div class="section-head"><h2>我的重难点</h2><button class="text-link" onclick="openAnnotations()">查看全部 ↗</button></div><div class="tags"><button class="chip ${n.important?'active':''}" aria-pressed="${n.important}" onclick="toggleAnnotation('${kind}','${id}','important')">${n.important?'★ 已标重点':'☆ 标记重点'}</button><button class="chip ${n.difficult?'active':''}" aria-pressed="${n.difficult}" onclick="toggleAnnotation('${kind}','${id}','difficult')">${n.difficult?'◆ 已标难点':'◇ 标记难点'}</button></div><form onsubmit="saveAnnotation(event,'${kind}','${id}')"><label class="annotation-label">我的笔记<textarea id="annotation-note" name="note" maxlength="600" placeholder="记下重要结论、还没理解的问题，或老师的讲解…">${esc(n.note)}</textarea></label><label class="annotation-label">摘录原文<textarea id="annotation-excerpt" name="excerpt" maxlength="400" placeholder="可选择阅读区的文字后点击“摘录选中文字”，也可手动填写。">${esc(n.excerpt)}</textarea></label><p class="muted">${kind==='textbook'?'可在“查看本页识别文字”中选择教材文字。':'可从上方课件正文选择文字。'}笔记和摘录仅自己可见。</p><div class="detail-actions"><button type="button" class="btn ghost" onclick="captureExcerpt()" onpointerdown="rememberExcerpt()">摘录选中文字</button><button class="btn" type="submit">保存重难点</button></div><p id="annotation-save-status" class="muted" role="status"></p></form></section>`}
let pendingExcerpt='';
function rememberExcerpt(){const selection=window.getSelection?.();const anchor=selection?.anchorNode,focus=selection?.focusNode;const valid=node=>(node?.nodeType===1?node:node?.parentElement)?.closest?.('.course-body,.textbook-text');if(valid(anchor)&&valid(focus)&&selection.toString().trim())pendingExcerpt=selection.toString().trim().slice(0,400)}
function captureExcerpt(){if(!pendingExcerpt)rememberExcerpt();if(!pendingExcerpt){toast('请先选中教材识别文字或课件正文中的一段文字');return}$('#annotation-excerpt').value=pendingExcerpt;pendingExcerpt='';$('#annotation-save-status').textContent='摘录已填入，点击“保存重难点”保存。'}
function upsertAnnotation(kind,id,values){const previous=pageAnnotation(kind,id)||{kind,pageId:id,important:false,difficult:false,note:'',excerpt:''},next={...previous,...values,updatedAt:Date.now()};annotations=annotations.filter(n=>!(n.kind===kind&&n.pageId===id));if(next.important||next.difficult||next.note.trim()||next.excerpt.trim())annotations.unshift(next);persist()}
function toggleAnnotation(kind,id,field){if(!user||!['important','difficult'].includes(field))return;const old=pageAnnotation(kind,id);const note=$('#annotation-note')?.value??old?.note??'',excerpt=$('#annotation-excerpt')?.value??old?.excerpt??'';upsertAnnotation(kind,id,{[field]:!old?.[field],note,excerpt});render();toast('重难点标记已更新')}
function saveAnnotation(e,kind,id){e.preventDefault();if(!user)return;upsertAnnotation(kind,id,{note:e.target.elements.note.value.trim(),excerpt:e.target.elements.excerpt.value.trim()});$('#annotation-save-status').textContent='已保存，可在知识库的“我的重难点”查看。';toast('重难点已保存')}
function openAnnotations(){showFavorites=false;showAnnotations=true;mapSearch='';if(tab==='library')render();else location.hash='library'}
function filterAnnotations(filter){annotationFilter=filter;render()}
function annotatedPages(){return annotations.map(n=>{const source=n.kind==='textbook'?(textbookEnabled?textbook:null):(courseEnabled?course:null);const p=source?.pages.find(p=>p.id===n.pageId);return p?{...n,title:p.title,sourceLabel:n.kind==='textbook'?'教材 · '+p.label:'课件 · 第 '+p.number+' 页'}:null}).filter(Boolean).sort((a,b)=>b.updatedAt-a.updatedAt)}
function openAnnotation(kind,id){const n=pageAnnotation(kind,id);query=n?.excerpt?.slice(0,200)||'';if(kind==='textbook')openTextbook(id);else openCourse(id)}
function annotationLibrary(){const all=annotatedPages(),found=all.filter(n=>annotationFilter==='all'||annotationFilter==='important'&&n.important||annotationFilter==='difficult'&&n.difficult);return `<section class="panel annotation-library" id="my-annotations"><div class="section-head"><div><div class="eyebrow">MY STUDY NOTES</div><h2>我的重难点</h2></div><span class="muted">${all.length} 页</span></div><p class="muted">阅读时标记的重点、难点和笔记，按最近修改排序。</p><div class="tags"><button class="chip ${annotationFilter==='all'?'active':''}" onclick="filterAnnotations('all')">全部</button><button class="chip ${annotationFilter==='important'?'active':''}" onclick="filterAnnotations('important')">★ 重点</button><button class="chip ${annotationFilter==='difficult'?'active':''}" onclick="filterAnnotations('difficult')">◆ 难点</button></div>${found.length?found.map(n=>`<article class="annotation-card"><div class="tags">${n.important?'<span class="category">★ 重点</span>':''}${n.difficult?'<span class="category">◆ 难点</span>':''}</div><h3>${esc(n.title)}</h3><small class="muted">${esc(n.sourceLabel)}</small>${n.excerpt?`<blockquote>${esc(n.excerpt)}</blockquote>`:''}${n.note?`<p class="annotation-note">${esc(n.note)}</p>`:''}<div class="detail-actions"><button class="btn ghost" onclick="openAnnotation('${n.kind}','${n.pageId}')">返回原页 ↗</button></div></article>`).join(''):'<div class="empty">暂无这类记录。阅读教材或课件时，可以标记重点、难点，或保存自己的笔记。</div>'}<button class="text-link" onclick="showAnnotations=false;render()">收起重难点</button></section>`}
function favoriteCards(){return saved.map(getCard).filter(Boolean)}
function openFavorites(){showFavorites=true;showAnnotations=false;if(tab==='library')render();else location.hash='library'}
function closeFavorites(){showFavorites=false;render()}
function favoritesLibrary(){const favorites=favoriteCards();return pageHead('收藏的知识卡片','把想反复理解的知识，收在一起。','MY FAVORITE CARDS')+`<div class="reader-top"><button class="text-link" onclick="closeFavorites()">← 返回全部知识库</button><span class="muted">${favorites.length} 张收藏卡片</span></div>${favorites.length?`<div class="knowledge-grid">${favorites.map(cardHTML).join('')}</div>`:'<div class="panel empty"><h3>还没有收藏的知识卡片</h3><p>打开任意知识卡片，点击“收藏卡片”，就可以在这里集中查看。</p><button class="btn ghost" onclick="closeFavorites()">浏览知识卡片 ↗</button></div>'}`}
function library(){if(showFavorites)return favoritesLibrary();const count=annotatedPages().length,entry=`<section class="panel annotation-entry"><div><span class="category">我的学习整理</span><h3>收藏的知识卡片</h3><p class="muted">${favoriteCards().length} 张卡片 · 随时打开复习</p></div><button class="btn ghost" onclick="openFavorites()">查看收藏 ↗</button></section><section class="panel annotation-entry"><div><span class="category">我的学习整理</span><h3>我的重难点</h3><p class="muted">${count} 页标记与笔记 · 点击回到原页</p></div><button class="btn ghost" onclick="openAnnotations()">查看重难点 ↗</button></section>`;if(showAnnotations)return pageHead('我的重难点','把重点与难点，留在自己的知识库里。','MY KNOWLEDGE LIBRARY')+annotationLibrary()+`<button class="text-link" onclick="showAnnotations=false;render()">← 返回全部知识库</button>`;const base=libraryBase(),marker=searchHTML();return base.replace(marker,entry+marker)}

function openCardSource(cardId,kind,pageId){const c=getCard(cardId);if(!c?.sources.some(s=>s.kind===kind&&s.pageId===pageId))return;query=c.title;if(kind==='textbook')openTextbook(pageId);else openCourse(pageId)}
function mobileMapDiagram(selected,visible,links,g){return `<div class="map-mobile-diagram"><div class="map-mobile-center">${esc(selected.label)}</div><div class="map-mobile-branches">${visible.map(id=>{const n=g.nodes.find(n=>n.id===id),e=links.find(e=>e.from===id||e.to===id);return `<button onclick="focusMap('${id}')"><small>${e.from===selected.id?'→':'←'} ${esc(e.label)}</small><strong>${esc(n.label)}</strong><span>展开节点 ↗</span></button>`}).join('')}</div><p class="muted">→ 当前概念指向该节点；← 该节点指向当前概念。</p></div>`}
document.addEventListener?.('selectionchange',()=>{if(user&&['course','textbook'].includes(tab))rememberExcerpt()});
function account(){return accountBase()+aiAdminSettings()}
boot();
